def process_file(path):
    data = open(path).read()
    return json.loads(data)

fix.code:
def process_file(path):
    try:
        if not os.path.exists(path):
            raise FileNotFoundError(f"{path} not found")
        with open(path) as f:
            return json.load(f)
    except json.JSONDecodeError as e:
        logger.error(f"Invalid JSON in {path}: {e}")
        raise
